declare const flag:boolean; declare function opaque(value?:unknown):unknown;
export const conditional=()=>flag?'left':'right';
export const constant=()=>true?'left':'right';
const condition=true; export const aliascondition=()=>condition?'left':'right';
export const returns=()=>{if(flag)return 'left';return 'right'};
export const incomplete=()=>{if(flag)return 'left'};
export const unreachable=()=>{return 'left';return 'right'};
export const reassigned=()=>{let id='old';id='new';return id};
export const selfassigned=()=>{let id='old';id=id;return id};
export const compound=()=>{let id='old';id+='new';return id};
export const branchassign=()=>{let id='old';if(flag)id='new';return id};
export const mutatedobject=()=>{const object={id:'old'};object.id='new';return object};
export const escapedobject=()=>{const object={id:'old'};opaque(object);return object};
export const branchunknown=()=>{if(flag)return 'left';return opaque()};
export const spreadfirst=()=>({...{id:'old'},id:'new'}).id;
export const spreadopaque=()=>({id:'old',...opaque()}).id;
export const spreadexplicit=()=>({...opaque(),id:'new'}).id;
export const spreadknown=()=>({...{id:'old'}}).id;
export const computed=()=>({['id']:'known'}).id;
export const method=()=>({id(){return 'method'}}).id();
export const localalias=()=>{const id='same';return id};
export const localshadow=()=>{const id='outside';{const id='inside';return id}};
export const branchlocal=()=>{const id=flag?'left':'right';return id};
let globalid='old';globalid='new';export const globalmutation=()=>globalid;
const immutableid='quiet';opaque(immutableid);export const globalimmutable=()=>immutableid;
export const closure=()=>{const id='captured';return (()=>id)()};
